onChange.script:
if origin in ['Browser', 'BindingWriteback']:
	r, g, b = self.custom.rgb
	self.custom.color = '#%02x%02x%02x' % (r, g, b)

transforms.code:
icons = value.icons
filter = value.filter.lower() if (value.filter or None) is not None else None

if filter is None: 
	return icons
else:
	return [i for i in icons if filter in i.path.split('/')[-1].lower()]

group = value.split('/')[0] if (value or None) is not None else 'kanoa'

for option in self.custom.options.groupOptions:
	if group == option.value:
		return group

return 'material'
